question.template:
"""Grader for the UniCV "predict the result" prototype (unicv_python3_predict).

The question author writes, in Global extra, a list of items: expressions whose
value (and type) the student must predict, and short programs whose output the
student must write. Values may be randomised with Twig template parameters, so
each attempt can have different numbers. The correct answers are never written
by the author: this grader computes them by running the code with Python.

Global extra format:
    ## context              code run before every item and shown to the student
    ## expressions          one expression per line: the student gives value and type
    ## values               one expression per line: the student gives the value only
    ## output [input: a; b] the following lines are a program: the student writes its output

The student's answer is {"answers": ["[[value, type], ...]"]}, one pair per item.
The result of each answer is written in the feedback as
<span class="unicv-pr-cell" data-item="N" data-cell="v|t" data-ok="1|0">text</span>.
"""
import ast
import builtins
import html
import io
import json
import math
import re
import signal
import sys

STUDENT_ANSWER = """{{ STUDENT_ANSWER | e('py') }}"""
QUESTION_ANSWER = """{{ QUESTION.answer | e('py') }}"""
GLOBAL_EXTRA = """{{ QUESTION.globalextra | e('py') }}"""
ALL_OR_NOTHING = "{{ QUESTION.allornothing }}" == "1"
IS_PRECHECK = "{{ IS_PRECHECK }}" == "1"

try:
    PARAMS = json.loads("""{{ QUESTION.parameters | json_encode | e('py') }}""")
except ValueError:
    PARAMS = {}
if not isinstance(PARAMS, dict):  # Twig encodes an empty set of parameters as []
    PARAMS = {}

SHOW_CORRECT = PARAMS.get('showcorrect', False)
REQUIRE_QUOTES = PARAMS.get('requirequotes', False)
ECHO_INPUT = PARAMS.get('echostandardinput', True)
TIMEOUT = float(PARAMS.get('timeout', 2))
MAX_OUTPUT = int(PARAMS.get('maxoutputlength', 5000))

TYPE_NAMES = ['int', 'float', 'str', 'bool', 'list', 'tuple', 'dict', 'set', 'NoneType', 'range', 'Error']


# ---------------------------------------------------------------------------
# Reading the items
# ---------------------------------------------------------------------------

def expand(text):
    """Replace any {{ name }} left in the text by the template parameter of that name."""
    def value(match):
        name = match.group(1)
        if name in PARAMS:
            v = PARAMS[name]
            return v if isinstance(v, str) else json.dumps(v)
        return match.group(0)
    return re.sub(r'\{\{\s*([A-Za-z_]\w*)\s*\}\}', value, text)


SECTION = re.compile(r'^##\s*(context|expressions|values|output)\b(.*)$', re.I)


def parse(text):
    """The context code and the list of items of the question."""
    lines = expand(text).replace('\r\n', '\n').split('\n')
    if not any(SECTION.match(line) for line in lines):
        lines = ['## expressions'] + lines
    context, items = [], []
    kind, body, arg = None, [], ''

    def close():
        if kind == 'context':
            context.extend(body)
        elif kind in ('expressions', 'values'):
            for line in body:
                code = line.strip()
                if code and not code.startswith('#'):
                    items.append({'kind': 'expr', 'code': code, 'typed': kind == 'expressions'})
        elif kind == 'output':
            code = '\n'.join(body).strip('\n')
            if code.strip():
                found = re.search(r'input\s*:\s*(.*)$', arg, re.I)
                stdin = [s.strip() for s in found.group(1).split(';')] if found else []
                items.append({'kind': 'output', 'code': code, 'input': stdin})

    for line in lines:
        match = SECTION.match(line)
        if match:
            close()
            kind, body, arg = match.group(1).lower(), [], match.group(2)
        else:
            body.append(line)
    close()
    return '\n'.join(context).strip('\n'), items


def read_answers(answer):
    try:
        data = json.loads(answer)
        raw = data.get('answers', [''])
        raw = raw[0] if isinstance(raw, list) else raw
        if isinstance(raw, str) and raw.startswith('AUTO:'):
            return raw
        pairs = json.loads(raw) if raw else []
        return [(str(p[0]) if p else '', str(p[1]) if len(p) > 1 else '') for p in pairs]
    except (ValueError, TypeError, AttributeError, IndexError):
        return []


# ---------------------------------------------------------------------------
# Running code
# ---------------------------------------------------------------------------

class TimeLimit(Exception):
    pass


class OutOfInput(Exception):
    pass


def on_alarm(signum, frame):
    raise TimeLimit()


def run(context, code, mode, stdin_lines=()):
    """Run the context and then evaluate (mode 'eval') or execute (mode 'exec') the code.
    Returns (value or printed output, name of the exception raised or '')."""
    out = io.StringIO()
    stdin = io.StringIO(''.join(line + '\n' for line in stdin_lines))
    names = dict(vars(builtins))

    def echo_input(prompt=''):
        out.write(str(prompt))
        line = stdin.readline()
        if not line:
            raise OutOfInput()
        line = line.rstrip('\n')
        if ECHO_INPUT:
            out.write(line + '\n')
        return line

    def to_out(*values, sep=' ', end='\n', file=None, flush=False):
        out.write((sep if sep is not None else ' ').join(str(v) for v in values) + (end if end is not None else '\n'))

    names['input'] = echo_input
    names['print'] = to_out
    scope = {'__name__': '__main__', '__builtins__': names}
    result, error = None, ''
    signal.signal(signal.SIGALRM, on_alarm)
    signal.setitimer(signal.ITIMER_REAL, TIMEOUT)
    try:
        if context.strip():
            exec(compile(context, 'context', 'exec'), scope)
        if mode == 'eval':
            result = eval(compile(code, 'expression', 'eval'), scope)
        else:
            exec(compile(code, 'program', 'exec'), scope)
            result = out.getvalue()
    except TimeLimit:
        error = 'TimeLimit'
    except OutOfInput:
        error = 'EOFError'
    except SystemExit:
        result = out.getvalue()
    except BaseException as exc:
        error = type(exc).__name__
        if mode == 'exec':
            result = out.getvalue()
    finally:
        signal.setitimer(signal.ITIMER_REAL, 0)
    if isinstance(result, str) and mode == 'exec' and len(result) > MAX_OUTPUT:
        result = result[:MAX_OUTPUT]
    return result, error


# ---------------------------------------------------------------------------
# Comparing answers
# ---------------------------------------------------------------------------

def same(a, b):
    """Equality that also requires the same types (so 4 is not 4.0 and 1 is not True)."""
    if type(a) is not type(b):
        return False
    if isinstance(a, float):
        return math.isclose(a, b, rel_tol=1e-9, abs_tol=1e-9) or (math.isnan(a) and math.isnan(b))
    if isinstance(a, (list, tuple)):
        return len(a) == len(b) and all(same(x, y) for x, y in zip(a, b))
    if isinstance(a, dict):
        return a.keys() == b.keys() and all(same(a[k], b[k]) for k in a)
    return a == b


def value_ok(text, expected):
    s = text.strip()
    if not s:
        return False
    try:
        literal = ast.literal_eval(s)
        if same(literal, expected):
            return True
    except (ValueError, SyntaxError, TypeError, MemoryError, RecursionError):
        literal = None
    if isinstance(expected, str):
        return not REQUIRE_QUOTES and s == expected
    return ''.join(s.split()) == ''.join(repr(expected).split())


def type_name(value):
    return type(value).__name__


def normalise(text):
    lines = [line.rstrip() for line in str(text).replace('\r\n', '\n').split('\n')]
    while lines and not lines[-1]:
        lines.pop()
    return '\n'.join(lines)


def shown(value):
    return repr(value)


# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------

def cell(item, cell_name, ok, text):
    return (f'<span class="unicv-pr-cell" data-item="{item}" data-cell="{cell_name}" data-ok="{1 if ok else 0}" '
            f'style="display:none">{html.escape(text)}</span>')


def pre(text):
    return f'<pre style="margin:0;white-space:pre-wrap">{html.escape(text)}</pre>'


def main():
    context, items = parse(GLOBAL_EXTRA)
    outcome = {'fraction': 0.0}
    if not items:
        outcome['prologuehtml'] = "<div class='coderunner-test-results bad'><h3>This question has no items</h3><p>Please tell your teacher.</p></div>"
        return outcome

    # The correct answers, computed now.
    expected = []
    problems = []
    if context.strip():
        _, error = run(context, '', 'exec')
        if error:
            problems.append(f'the context code raises {error}')
    for k, item in enumerate(items):
        if item['kind'] == 'expr':
            value, error = run(context, item['code'], 'eval')
            if error == 'TimeLimit':
                problems.append(f'item {k + 1} takes too long')
            expected.append({'error': error, 'value': value, 'type': 'Error' if error else type_name(value)})
        else:
            output, error = run(context, item['code'], 'exec', item['input'])
            if error == 'TimeLimit':
                problems.append(f'item {k + 1} takes too long (endless loop?)')
            elif error:
                # A program that stops with an error: the name of the error is its last line.
                output = (output or '') + ('' if not output or output.endswith('\n') else '\n') + error + '\n'
            expected.append({'error': error, 'value': output})

    answers = read_answers(STUDENT_ANSWER)
    teacher = read_answers(QUESTION_ANSWER)
    style = 'style="border:1px solid #c4cdd5;padding:4px 8px;vertical-align:top"'

    # The teacher's answer: a check of the question, showing every correct answer.
    if isinstance(answers, str):
        if not (isinstance(teacher, str) and answers == teacher):
            outcome['prologuehtml'] = "<div class='coderunner-test-results bad'><h3>Invalid answer</h3></div>"
            return outcome
        if problems:
            outcome['prologuehtml'] = ("<div class='coderunner-test-results bad'><h3>The question has problems</h3><ul>" +
                                       ''.join(f'<li>{html.escape(p)}</li>' for p in problems) + '</ul></div>')
            return outcome
        rows = []
        for k, (item, exp) in enumerate(zip(items, expected)):
            if item['kind'] == 'expr':
                answer = exp['error'] if exp['error'] else shown(exp['value'])
                kind = exp['type'] if item['typed'] else ''
            else:
                answer = exp['value']
                kind = 'output'
            rows.append(f'<tr><td {style}>{k + 1}</td><td {style}>{pre(item["code"])}</td><td {style}>{pre(answer)}</td><td {style}>{html.escape(kind)}</td></tr>')
        outcome['fraction'] = 1.0
        outcome['prologuehtml'] = ("<div class='coderunner-test-results good'><h3>The correct answers for these values</h3></div>"
                                   f'<table style="border-collapse:collapse"><tr><th {style}>#</th><th {style}>Item</th>'
                                   f'<th {style}>Answer</th><th {style}>Type</th></tr>' + ''.join(rows) + '</table>')
        return outcome

    if problems:
        outcome['prologuehtml'] = ("<div class='coderunner-test-results bad'><h3>This question has a problem</h3><p>"
                                   + html.escape('; '.join(problems)) + '. Please tell your teacher.</p></div>')
        return outcome

    total = right = 0
    marks = []
    rows = []
    for k, (item, exp) in enumerate(zip(items, expected)):
        value, kind = answers[k] if k < len(answers) else ('', '')
        cells = []
        if item['kind'] == 'expr':
            if exp['error']:
                v_ok = value.strip() == exp['error']
                correct_value = exp['error']
            else:
                v_ok = value_ok(value, exp['value'])
                correct_value = shown(exp['value'])
            cells.append(('v', v_ok, correct_value))
            if item['typed']:
                t_ok = kind.strip() == exp['type']
                cells.append(('t', t_ok, exp['type']))
        else:
            v_ok = normalise(value) == normalise(exp['value'])
            cells.append(('v', v_ok, exp['value'].rstrip('\n')))
        for name, ok, correct in cells:
            total += 1
            right += ok
            if ok:
                text = 'Correct'
            elif SHOW_CORRECT:
                text = 'Correct answer: ' + correct
            else:
                text = 'Not correct'
            marks.append(cell(k, name, ok, text))
        ok_all = all(c[1] for c in cells)
        mark = '<span style="color:#2f7d32;font-weight:700">✓</span>' if ok_all else \
            '<span style="color:#a51d2a;font-weight:700">✗</span>'
        answer_text = value if item['kind'] == 'output' else (value + (f'  ({kind})' if item['typed'] and kind else ''))
        correct_col = ''
        if SHOW_CORRECT and not ok_all:
            c = [x[2] for x in cells]
            correct_col = c[0] + (f'  ({c[1]})' if len(c) > 1 else '')
        rows.append((k, item['code'], answer_text, mark, correct_col))

    if ALL_OR_NOTHING:
        outcome['fraction'] = 1.0 if right == total else 0.0
    else:
        outcome['fraction'] = right / total if total else 0.0
    good = right == total
    head = (f"<div class='coderunner-test-results {'good' if good else 'bad'}'><h3>"
            f"{'All your answers are correct.' if good else f'{right} of your {total} answers are correct.'}</h3></div>")
    show_col = SHOW_CORRECT and not good
    table = (f'<table style="border-collapse:collapse;margin-top:8px"><tr><th {style}>#</th><th {style}>Item</th>'
             f'<th {style}>Your answer</th><th {style}></th>' + (f'<th {style}>Correct answer</th>' if show_col else '') + '</tr>')
    for k, code, answer_text, mark, correct_col in rows:
        table += (f'<tr><td {style}>{k + 1}</td><td {style}>{pre(code)}</td><td {style}>{pre(answer_text)}</td><td {style}>{mark}</td>'
                  + (f'<td {style}>{pre(correct_col)}</td>' if show_col else '') + '</tr>')
    table += '</table>'
    outcome['prologuehtml'] = head + table + ''.join(marks)
    if IS_PRECHECK:
        outcome['fraction'] = 1.0
        outcome['prologuehtml'] = "<p class='precheckresult'>Your answers have been saved.</p>"
    return outcome


print(json.dumps(main()))
